```cpp
#include <iostream>
#include <string>
#include <cstring> // For memcpy

size_t copyBytes(void* destination, const void* source, size_t numBytes) {
    std::memcpy(destination, source, numBytes);
    return numBytes;
}

size_t stringLength(const std::string& str) {
    return str.length();
}

int main() {
    const char buffer[10] = {}; // Initialize a 10-byte buffer
    const std::string sourceString = "Hello";
    const size_t numBytesToCopy = stringLength(sourceString);

    copyBytes(&buffer[0], sourceString.c_str(), numBytesToCopy);

    std::cout << "Copied 'Hello' into buffer: " << buffer << "\n";

    return 0;
}
```

