// Function to calculate monthly sales
unsigned int getMonthlySales(unsigned int month) {
    static unsigned seed[] = {0};
    unsigned long *p = seed;
    int key = (month < 7) ? (month * 317 % 1931) : -208 + (month * 317 % 1931);
    while (*p >= key) {
