    FILE *fp;  // File pointer
    char path[FILENAME_MAX] = "/safe/";  // The directory path
    char file[FILENAME_MAX];  // The name of the file to open
    size_t num_read;  // Number of characters read from the file

    printf("Enter the name of the file: ");
    scanf("%s", file);
    strcat(path, file);  // Concatenate the directory path with the file name

    fp = fopen(path, "r");  // Open the file in read mode
    if (fp == NULL) {  // If the file could not be opened
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    char buffer[256];  // Buffer to store the data read from the file
    while ((num_read = fread(buffer, sizeof(char), sizeof(buffer) - 1, fp)) > 0) {
        buffer[num_read] = '\0';  // Ensure null-terminated
        printf("%s\n", buffer);  // Print the data read from the file
