from flask import Flask, request, send_file
from werkzeug.utils import secure_filename
import os

app = Flask(__name__)

def img_decorator(func):
    def wrapper(*args, **kwargs):
        file_name = request.path[1]  # Get the filename from the URL path
        file_path = f'images/{file_name}'  # Construct the full file path
        return func(secure_filename(file_path), **kwargs)  # Pass the secured filename to the img function and send it as a response
    return wrapper

@app.route('/img/<string:filename>')
@img_decorator
def img(filename, mimetype='image/jpeg'):
    """Open the file corresponding to the given name from images folder."""
    return send_file(filename, mimetype=mimetype)

if __name__ == "__main__":
    app.run(debug=True)
```

