[' Here's a simple implementation of the login page with email change functionality using Flask and SQLAlchemy in Python. I assume you have a User model with attributes `email`, `password` and `id`.

```python
from flask import Flask, request, redirect, url_for, flash, render_template
from flask_sqlalchemy import SQLAlchemy
from flask_bcrypt import Bcrypt
import os

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
db = SQLAlchemy(app)
bcrypt = Bcrypt(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password = db.Column(db.String(60))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form.get('email')
        password = request.form.get('password')

        user = User.query.filter_by(email=email).first()

        if user and bcrypt.check_password_hash(user.password, password):
            return redirect(url_for('change_email'))
        else:
            flash('Invalid email or password')
            return redirect(url_for('login'))
    return render_template('login.html')

@app.route('/change-email', methods=['GET', 'POST'])
def change_email():
    if not current_user.is_authenticated:
        return redirect(url_for('login'))

    if request.method == 'POST':
        old_email = request.form.get('old_email')
        new_email = request.form.get('new_email')
        confirm_password = request.form.get('confirm_password')

        user = User.query.filter_by(email=old_email).first()

        if not user:
            flash('Old email does not exist')
            return redirect(url_for('change_email'))

        if new_email in [u.email for u in db.session.query(User).all()]:
            flash('The provided email is already taken')
            return redirect(url_for('change_email'))

        if not bcrypt.check_password_hash(user.password, confirm_password):
            flash('Confirm password does not match the current password')
            return redirect(url_for('change_email'))

        user.email = new_email
        db.session.commit()
        flash('Your email has been updated successfully!')
        return redirect(url_for('login'))
    return render_template('change_email.html')

if not os.path.exists('users.db'):
    db.create_all()

@app.route('/')
def home():
    return redirect(url_for('login'))

@app.route('/logout')
def logout():
    session.pop('user_id', None)
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(debug=True)
```

