int main(int argc, char **argv) {
    // Check if the argument is provided
    if (argc != 2) {
        printf("Usage: ./a.out [buffer_size]\n");
        return -1;
    }

    // Convert the input to an integer and check for errors
    int buffer_size = atoi(argv[1]);
    if (buffer_size <= 0) {
        printf("Error: Invalid buffer size. Buffer size must be a positive integer.\n");
        return -1;
    }

    // Allocate memory for the buffer and set all elements to zero
    int *buffer = malloc(buffer_size * sizeof(int));
    if (buffer == NULL) {
        perror("Error: Failed to allocate memory.\n");
        return -1;
    }
