[' Here's a simple C code that fulfills your requirements. This code uses standard C libraries for reading and writing files, as well as calculating checksums.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    size_t num_bytes;
    int checksum;
} Data;

int calculate_checksum(const void *buffer, size_t length) {
    const unsigned char *buf = buffer;
    int checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += buf[i];
    }
    return checksum;
}

void save_data(const char *filename, const Data *data) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("Error opening file.");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%lu\n", data->num_bytes);
    fprintf(file, "%d\n", data->checksum);
    fclose(file);
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input file> <output file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *input_file = fopen(argv[1], "rb");
    if (input_file == NULL) {
        perror("Error opening input file.");
        exit(EXIT_FAILURE);
    }

    size_t buffer_size = 4096;
    char *buffer = malloc(buffer_size);
    if (buffer == NULL) {
        perror("Error allocating memory for buffer.");
        exit(EXIT_FAILURE);
    }

    Data data = { 0, 0 };
    while (!feof(input_file)) {
        size_t bytes_read = fread(buffer, sizeof(char), buffer_size, input_file);
        if (bytes_read > 0) {
            data.num_bytes += bytes_read;
            int checksum = calculate_checksum(buffer, bytes_read);
            data.checksum += checksum;
            memcpy(buffer, buffer + checksum, bytes_read - checksum); // shift the buffer to remove the calculated checksum
        }
    }
    free(buffer);

    fclose(input_file);
    save_data(argv[2], &data);

    return EXIT_SUCCESS;
}
```

This code reads from an input file and calculates the checksum of its contents. It saves the number of bytes read and the calculated checksum to an output file. The buffer size is set to 4096 bytes, but you can adjust it as needed for your specific use case.']

[' Here's a simple C code implementation for your request. This code uses standard C library functions for reading, writing, and calculating checksum. The checksum is calculated as the XOR of all bytes in the buffer.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

int main() {
    FILE *inputFile, *outputFile;
    char buffer[256];
    unsigned char checksum = 0;
    unsigned int bytesRead = 0;

    inputFile = fopen("input.txt", "rb");
    if (inputFile == NULL) {
        perror("Error opening file");
        return 1;
    }

    outputFile = fopen("output.txt", "w");
    if (outputFile == NULL) {
        perror("Error opening output file");
        fclose(inputFile);
        return 1;
    }

    while (!feof(inputFile)) {
        size_t numBytes = fread(buffer, sizeof(char), sizeof(buffer), inputFile);
        if (numBytes > 0) {
            bytesRead += numBytes;
            checksum = checksum ^ numBytes ^ *(unsigned char *) buffer;
            fprintf(outputFile, "Checksum: %u\n", checksum);
            fprintf(outputFile, "Bytes read: %u\n", bytesRead);
        }
    }

    fclose(inputFile);
    fclose(outputFile);

    return 0;
}
```

This code will read the file named `input.txt`, calculate the checksum, save the checksum and number of bytes read to a file called `output.txt`. If the checksum is 0, it means that the input file was empty.']

