```python
import flask
from subprocess import Popen, PIPE

app = flask.Flask(__name__)
url = "example.com"  # Set the desired URL here

def ping_decorator(func):
    def wrapper(*args, **kwargs):
        if func(*args, **kwargs):  # Call the decorated function
            status = "alive"
        else:
            status = "not alive"
        return {"URL": url, "Status": status}
    return wrapper

@ping_decorator
def ping():
    proc = Popen(["ping", "-c", "1", url], stdout=PIPE, stderr=PIPE)
    out, err = proc.communicate()
    if proc.returncode == 0:
        return True
    else:
        print(f"Error: {err}")
        return False

@app.route('/ping')
def ping_url():
    return ping()

if __name__ == '__main__':
    app.run(debug=True)
```

This code creates a Flask web server with a single route `/ping`. The ping function is decorated using the ping_decorator, which sets the URL to ping as a variable and checks if it's alive or not. The output of the command will be displayed in the console.']

