    float nums[3];
    char strNums[9][20];

    // Generate 3 random floats, convert them to strings, and concatenate them into a single string
    for (int i = 0; i < 3; ++i) {
        nums[i] = ((float)rand() / RAND_MAX); // Generate a random float between 0.0 and 1.0
        snprintf(strNums[i], sizeof(strNums[i]), "%f", nums[i]); // Convert the float to a string
    }

    char *result = malloc((3 + 1) * strlen(strNums[0])); // Allocate memory for the concatenated string
    strcpy(result, strNums[0]); // Copy the first string into the result buffer

    for (int i = 1; i < 3; ++i) {
        strcat(result, ","); // Add a comma between each number
        strcat(result, strNums[i]);
    }

    // Write the resulting string to a file named output.txt
    FILE *file = fopen("output.txt", "w");
    if (file != NULL) {
        fprintf(file, "%s", result);
        free(result); // Free the memory allocated for the concatenated string
        fclose(file);
    } else {
        printf("Failed to open output file.\n");
    }

    return 0;
}
```

