[' Here's a simple C code using the Boost.Beast asio library for handling HTTP requests and responses. This code defines a function `http_hello_page` that does what you described:

```cpp
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <cstdlib>
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <boost/asio/ip/tcp.hpp>
#include <boost/bind.hpp>

namespace http = boost::beast::http;
using tcp = boost::asio::ip::tcp;

void http_hello_page(http::request<http::string_body> req, std::ostream& output) {
    auto const username_key = "*username*";
    if (req.method() != http::verb::get || req.target().find(username_key) == std::string::npos) {
        output << "HTTP/1.0 400 Bad Request\r\nContent-Type: text/plain\r\nConnection: close\r\n\r\nError 400: Bad request\n";
        return;
    }

    std::string username = req.target().substr(username_key.length());
    std::stringstream ss;
    ss << "Hello, " << username << "!";

    http::response<http::string_body> response(http::status::ok, req.version());
    response.set(http::field::server, "My Server");
    response.set(http::field::content_type, "text/html");
    response.keep_alive(req.keep_alive());
    response.body() = ss.str();

    output << response | http::write_to(output);
}

int main(int argc, char* argv[]) {
    try {
        net::io_context ioc;
        tcp::acceptor acceptor{ioc, { { boost::asio::ip::make_address("0.0.0.0"), 8080 } } };
        for (;;) {
            tcp::socket socket{ioc};
            acceptor.accept(socket);
            http::request<http::string_body> req;
            boost::beast::flat_buffer buffer;
            http::read(boost::asio::streambuf{buffer}, socket, req, buffer.get_capacity());

            if (req.need_eof()) {
                break;
            }

            std::ostream output{&buffer};
            http_hello_page(req, output);
            boost::beast::flat_buffer response_buffer;
            http::write(boost::asio::streambuf{response_buffer}, req, http::response<http::string_body>{});
            socket.write_some(response_buffer.data(), response_buffer.size());
            socket.shutdown(tcp::socket::shutdown_both);
        }
    } catch (std::exception const& e) {
        std::cerr << "Error: " << e.what() << "\n";
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

