/* Escape HTML special characters */
char *escape_html(const char *unsafe) {
    int len = strlen(unsafe);
    char *escaped = malloc(len + 16); /* Estimate for worst case */
    int esclen = 0;

    for (int i = 0; unsafe[i]; ++i) {
        switch (unsafe[i]) {
            case '<':
                escaped[esclen++] = '&';
                escaped[esclen++] = 'l';
                escaped[esclen++] = 't';
                escaped[esclen++] = ';';
                break;
            case '>':
                escaped[esclen++] = '&';
                escaped[esclen++] = 'g';
                escaped[esclen++] = 't';
                escaped[esclen++] = ';';
                break;
            case '&':
                escaped[esclen++] = '&';
                escaped[esclen++] = 'a';
                escaped[esclen++] = 'm';
                escaped[esclen++] = 'p';
                escaped[esclen++] = ';';
                break;
            default:
                escaped[esclen++] = unsafe[i];
        }
    }

    escaped[esclen] = '\0';
    return escaped;
}

/* Function to handle the request and response */
